customEChartConfig:
{{ ((chartType) => ( 
(() => {
  const rows = qryTrend.data || [];
  const perioden = [...new Set(rows.map(r => r.label))];
  const kategorien = [...new Set(rows.map(r => r.kategorie))];
  const gewaehlt = MultiSelect_kategorien.selectedOptionValues || [];
  const n = perioden.length;

  return {
    title: { text: 'Trend nach Kategorie', left: 'center', top: 10 },
    tooltip: { trigger: 'axis' },
    color: ['#5470c6', '#ee6666', '#91cc75', '#fac858', '#73c0de', '#3ba272',
            '#fc8452', '#9a60b4', '#ea7ccc', '#8d6e63', '#26a69a', '#546e7a'],
    legend: {
      type: 'scroll',
      bottom: 15,
      itemGap: 20,
      data: gewaehlt,
      selected: Object.fromEntries(kategorien.map(k => [k, gewaehlt.includes(k)]))
    },
    grid: { left: 20, right: 40, top: 60, bottom: 80, containLabel: true },
    xAxis: {
      type: 'category',
      boundaryGap: false,
      axisLabel: {
        margin: 12,
        rotate: n > 14 ? 45 : 0,
        interval: n > 40 ? Math.ceil(n / 20) - 1 : 0
      },
      data: perioden
    },
    yAxis: { type: 'value', min: 0, axisLabel: { formatter: '{value} €' } },
    series: kategorien.map(k => ({
      name: k,
      type: 'line',
      smooth: 0.3,
      showSymbol: n <= 36,
      symbolSize: n > 24 ? 4 : 6,
      lineStyle: { width: n > 36 ? 1.5 : 2 },
      data: rows.filter(r => r.kategorie === k).map(r => r.betrag)
    }))
  };
})()
))(Chart2.chartType) }}
